import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import './Auth.css';

const Auth = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();
  const { login } = useAuth();

  const switchModeHandler = () => {
    setIsLogin(prevState => !prevState);
  };

  const submitHandler = (event) => {
    event.preventDefault();

    if (isLogin) {
      // In a real app, you would make an API call to your backend to verify credentials
      console.log('Logging in with:', email, password);
      const userData = {
        name: 'Jeevi', // Placeholder name
        email: email,
      };
      login(userData);
    } else {
      // In a real app, you would make an API call to your backend to register the user
      console.log('Signing up with:', name, email, password);
      const userData = {
        name: name,
        email: email,
      };
      login(userData); // Log the user in directly after signup
    }

    navigate('/'); // Navigate to home page after login/signup
  };

  return (
    <div className="auth-page">
      <div className="auth-form-container">
        <h2>{isLogin ? 'Login' : 'Sign Up'}</h2>
        <form onSubmit={submitHandler}>
          {!isLogin && (
            <div className="form-control">
              <label htmlFor="name">Name</label>
              <input 
                type="text" 
                id="name" 
                required 
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
          )}
          <div className="form-control">
            <label htmlFor="email">Email</label>
            <input 
              type="email" 
              id="email" 
              required 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="form-control">
            <label htmlFor="password">Password</label>
            <input 
              type="password" 
              id="password" 
              required 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          <div className="form-actions">
            <button type="submit">{isLogin ? 'Login' : 'Create Account'}</button>
          </div>
        </form>
        <button onClick={switchModeHandler} className="switch-button">
          {isLogin ? "Don't have an account? Sign Up" : 'Have an account? Login'}
        </button>
      </div>
    </div>
  );
};

export default Auth;
